import fs from 'node:fs'
import path from 'node:path'
import { spawn } from 'node:child_process'

export type CommandResult = {
  exitCode: number
  stdout: string
  stderr: string
  timedOut: boolean
}

export type CommandOptions = {
  cwd?: string
  env?: NodeJS.ProcessEnv
  timeoutMs?: number
  stdoutFilePath?: string
  stderrFilePath?: string
  stdinText?: string
}

export interface CommandExecutor {
  run(command: string, args: string[], options?: CommandOptions): Promise<CommandResult>
}

export class SpawnCommandExecutor implements CommandExecutor {
  async run(command: string, args: string[], options: CommandOptions = {}): Promise<CommandResult> {
    return new Promise((resolve, reject) => {
      const stdoutChunks: string[] = []
      const stderrChunks: string[] = []
      const stdoutStream = options.stdoutFilePath ? fs.createWriteStream(options.stdoutFilePath, { flags: 'a' }) : null
      const stderrStream = options.stderrFilePath ? fs.createWriteStream(options.stderrFilePath, { flags: 'a' }) : null
      const child = spawn(command, args, {
        cwd: options.cwd,
        env: options.env ?? process.env,
        stdio: 'pipe',
      })

      let timedOut = false
      let timeoutHandle: NodeJS.Timeout | undefined
      if (options.timeoutMs) {
        timeoutHandle = setTimeout(() => {
          timedOut = true
          child.kill('SIGTERM')
        }, options.timeoutMs)
      }

      child.stdout.on('data', (chunk: Buffer) => {
        const text = chunk.toString('utf8')
        stdoutChunks.push(text)
        stdoutStream?.write(text)
      })
      child.stderr.on('data', (chunk: Buffer) => {
        const text = chunk.toString('utf8')
        stderrChunks.push(text)
        stderrStream?.write(text)
      })
      child.on('error', (error) => {
        stdoutStream?.end()
        stderrStream?.end()
        reject(error)
      })
      child.on('close', (code) => {
        if (timeoutHandle) {
          clearTimeout(timeoutHandle)
        }
        stdoutStream?.end()
        stderrStream?.end()
        resolve({
          exitCode: code ?? 1,
          stdout: stdoutChunks.join(''),
          stderr: stderrChunks.join(''),
          timedOut,
        })
      })

      if (options.stdinText) {
        child.stdin.write(options.stdinText)
      }
      child.stdin.end()
    })
  }
}

export async function isCommandAvailable(executor: CommandExecutor, binary: string): Promise<boolean> {
  const locator = process.platform === 'win32' ? 'where' : 'which'
  const result = await executor.run(locator, [binary], { cwd: process.cwd(), timeoutMs: 5_000 })
  return result.exitCode === 0
}

export function ensureParentDirectory(filePath: string): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true })
}
